#include <stdio.h>
#include <string.h>
#include <time.h>

int main(void) {
    char cmd[16];
    int y, m, d, n;
    while (scanf("%15s", cmd) == 1) {
        if (strcmp(cmd, "add") != 0) continue;
        if (scanf("%d %d %d %d", &y, &m, &d, &n) != 4) continue;

        struct tm tmv;
        memset(&tmv, 0, sizeof(tmv));
        tmv.tm_year = y - 1900;
        tmv.tm_mon = m - 1;
        tmv.tm_mday = d;
        tmv.tm_hour = 12;
        time_t t = timegm(&tmv);

        int counted = 0;
        while (counted < n) {
            t += 86400;
            struct tm *cur = gmtime(&t);
            if (cur->tm_wday != 0 && cur->tm_wday != 6) {
                counted++;
            }
        }

        struct tm *result = gmtime(&t);
        printf("%04d-%02d-%02d\n", result->tm_year + 1900, result->tm_mon + 1, result->tm_mday);
    }
    return 0;
}

